<?php session_start(); require 'config/database.php'; require 'lib_security.php'; require 'lib_academic.php'; if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){verifyCsrf();$pdo->prepare('DELETE FROM users WHERE id=(SELECT user_id FROM students WHERE id=?)')->execute([(int)$_POST['delete']]);header('Location: students.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$name=trim($_POST['name']);$email=trim($_POST['email']);$roll=trim($_POST['roll_no']);$pid=(int)$_POST['program_id'];$term=trim($_POST['semester_or_year']);$pass=$_POST['password']??'';try{$pdo->beginTransaction();$h=password_hash($pass?:'Student@123',PASSWORD_DEFAULT);$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"student")');$s->execute([$name,$email,$h]);$uid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO students(user_id,roll_no,program_id,semester_or_year) VALUES(?,?,?,?)')->execute([$uid,$roll,$pid,$term]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==23000?'Email or roll number already exists.':$e->getMessage();}if(!isset($error)){header('Location: students.php');exit;}}
$programs=$pdo->query('SELECT * FROM programs ORDER BY FIELD(level,"HSSC","BS","ADP"),name')->fetchAll();$rows=$pdo->query('SELECT s.id,s.roll_no,s.semester_or_year,u.name,u.email,p.level,p.name program_name FROM students s JOIN users u ON u.id=s.user_id JOIN programs p ON p.id=s.program_id ORDER BY s.id DESC')->fetchAll();$pageTitle='Students';require'includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between"><h2>Students</h2><a href="admin.php" class="btn btn-outline-secondary">Dashboard</a></div><?php if(isset($error)):?><div class="alert alert-danger mt-3"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card shadow-sm my-3"><div class="card-body"><h5>Add Student</h5><form method="post" class="row g-2"><?php echo csrfField(); ?><div class="col-md-3"><input name="name" class="form-control" placeholder="Full name" required></div><div class="col-md-3"><input name="email" type="email" class="form-control" placeholder="Email" required></div><div class="col-md-2"><input name="roll_no" class="form-control" placeholder="Roll No" required></div><div class="col-md-2"><select name="program_id" id="studentProgram" class="form-select" required><option value="">Program</option><?php foreach($programs as $p):?><option value="<?=$p['id']?>"><?=$p['level']?> — <?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="semester_or_year" id="studentTerm" class="form-select" required><option value="">Term</option></select></div><div class="col-md-1"><input name="password" class="form-control" placeholder="Password"></div><div class="col-12"><button class="btn btn-primary">Create Student</button><small class="text-muted ms-2">Default password if blank: Student@123</small></div></form><script>const terms={HSSC:['Part-I','Part-II'],BS:['1st Semester','2nd Semester','3rd Semester','4th Semester','5th Semester','6th Semester','7th Semester','8th Semester'],ADP:['1st Year','2nd Year','1st Semester','2nd Semester','3rd Semester','4th Semester']};const p=document.getElementById('studentProgram'),t=document.getElementById('studentTerm');p.addEventListener('change',()=>{const level=p.options[p.selectedIndex]?.text.split(' — ')[0];t.innerHTML='<option value="">Term</option>'+(terms[level]||[]).map(x=>'<option>'+x+'</option>').join('');});</script></div></div><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Roll</th><th>Student</th><th>Email</th><th>Program</th><th>Term</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['roll_no'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=$r['level']?> — <?=htmlspecialchars($r['program_name'])?></td><td><?=htmlspecialchars($r['semester_or_year'])?></td><td><form method="post" class="d-inline" onsubmit="return confirm('Delete this student?')"><?php echo csrfField(); ?><button name="delete" value="<?=$r['id']?>" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require'includes/footer.php';?>
